import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_layernorm(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void layernorm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ y,
    int batch, long N, float eps)
{
    int b = blockIdx.x;

    // Build CuTe tensors for this batch row.
    Tensor gX = make_tensor(make_gmem_ptr(x), make_shape(batch, N), make_stride(N, Int<1>{}));
    Tensor gY = make_tensor(make_gmem_ptr(y), make_shape(batch, N), make_stride(N, Int<1>{}));
    Tensor gGamma = make_tensor(make_gmem_ptr(gamma), make_shape(N), make_stride(Int<1>{}));
    Tensor gBeta  = make_tensor(make_gmem_ptr(beta),  make_shape(N), make_stride(Int<1>{}));

    extern __shared__ double sdata[];
    double* s_sum   = sdata;
    double* s_sumsq = sdata + blockDim.x;

    double sum = 0.0;
    double sumsq = 0.0;

    for (long i = threadIdx.x; i < N; i += blockDim.x) {
        double v = (double)gX(b, i);
        sum += v;
        sumsq += v * v;
    }

    s_sum[threadIdx.x] = sum;
    s_sumsq[threadIdx.x] = sumsq;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sumsq[threadIdx.x] += s_sumsq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    __shared__ float mean_s, inv_std_s;
    if (threadIdx.x == 0) {
        double m = s_sum[0] / (double)N;
        double var = s_sumsq[0] / (double)N - m * m;
        mean_s = (float)m;
        inv_std_s = (float)(1.0 / sqrt(var + (double)eps));
    }
    __syncthreads();

    float mean = mean_s;
    float inv_std = inv_std_s;

    for (long i = threadIdx.x; i < N; i += blockDim.x) {
        float v = gX(b, i);
        float norm = (v - mean) * inv_std;
        float g = gGamma(i);
        float be = gBeta(i);
        gY(b, i) = norm * g + be;
    }
}

torch::Tensor cute_layernorm(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Expect float32 tensor");

    auto x_c = x.contiguous();
    auto gamma_c = gamma.contiguous();
    auto beta_c = beta.contiguous();

    int batch = (int)x_c.size(0);
    long N = x_c.numel() / batch;

    auto y = torch::empty_like(x_c);

    int threads = 512;
    dim3 grid(batch);
    size_t shmem = 2 * threads * sizeof(double);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    layernorm_kernel<<<grid, threads, shmem, stream>>>(
        x_c.data_ptr<float>(),
        gamma_c.data_ptr<float>(),
        beta_c.data_ptr<float>(),
        y.data_ptr<float>(),
        batch, N, (float)eps);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE layernorm launch failed");
    return y;
}
"""

cute_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_layernorm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs Layer Normalization using a custom CUTE kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.weight.to(device=x.device, dtype=x.dtype).contiguous()
        bias = self.bias.to(device=x.device, dtype=x.dtype).contiguous()
        return self._ext.cute_layernorm(x, weight, bias, self.eps)

